// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        // newOwner must be admissible: non-zero (required by C) and different from
        // the current owner, so the rule genuinely constrains the transfer target.
        vm.assume(newOwner != address(0));
        address currentOwner = c.owner();
        vm.assume(newOwner != currentOwner);

        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner);
    }
}
